<script>
(() => {
  const baseCoins = [
    [1,'Bitcoin','BTC',75612.78,-0.12,1.84,4.23,1510000000000,28435000000,20010000,'All Networks','Top'],
    [2,'Ethereum','ETH',2356.00,0.08,2.12,6.48,283600000000,14520000000,120100000,'Ethereum','Top'],
    [3,'Tether','USDT',1.00,0.01,0.02,0.03,111400000000,60350000000,111300000000,'Ethereum','Top'],
    [4,'BNB','BNB',612.41,-0.04,1.36,3.12,91800000000,1870000000,149530000,'BSC','Top'],
    [5,'Solana','SOL',182.22,0.45,3.84,12.61,82500000000,4230000000,452800000,'Solana','Top'],
    [6,'USD Coin','USDC',1.00,0.00,0.01,0.01,33800000000,6890000000,33790000000,'Base','Top'],
    [7,'XRP','XRP',0.61,-0.22,1.15,2.18,34500000000,1980000000,56500000000,'More','Trending'],
    [8,'Dogecoin','DOGE',0.18,0.11,2.08,8.02,25900000000,1650000000,143700000000,'More','Most Visited'],
    [9,'Cardano','ADA',0.74,-0.08,1.77,4.94,26200000000,890000000,35350000000,'More','Watchlist'],
    [10,'Avalanche','AVAX',38.55,0.09,2.51,10.42,14600000000,730000000,379000000,'More','Trending'],
    [11,'Polkadot','DOT',8.23,-0.06,1.26,5.21,11800000000,420000000,1433000000,'More','Watchlist'],
    [12,'Chainlink','LINK',18.37,0.19,3.11,9.07,10800000000,510000000,587000000,'Ethereum','Most Visited'],
    [13,'Toncoin','TON',6.74,0.05,2.44,11.36,23200000000,310000000,3440000000,'More','Trending'],
    [14,'Shiba Inu','SHIB',0.000029,-0.17,1.09,7.86,17100000000,890000000,589000000000000,'Ethereum','Most Visited'],
    [15,'Sui','SUI',1.63,0.32,4.07,16.22,2050000000,640000000,1258000000,'More','New']
  ];

  const categories = ['Top','Trending','Watchlist','Prediction Markets','Most Visited','New'];
  const networks = ['All Networks','BSC','Solana','Base','Ethereum','More'];

  function genRow(rank) {
    const t = baseCoins[(rank - 1) % baseCoins.length];
    const drift = ((rank % 9) - 4) * 0.0025;
    const price = t[3] * (1 + drift * 0.8);
    const h1 = t[4] + drift * 4;
    const h24 = t[5] + drift * 7;
    const d7 = t[6] + drift * 14;
    const cap = t[7] * (1 - (rank * 0.0032));
    const vol = t[8] * (1 - (rank * 0.0041));
    const supply = t[9] * (1 + (rank % 7) * 0.0004);
    return {
      rank,
      name: t[1],
      symbol: t[2],
      price,
      h1,
      h24,
      d7,
      marketCap: Math.max(cap, 20000000),
      volume: Math.max(vol, 1000000),
      supply,
      network: t[10],
      category: categories[rank % categories.length] === 'Prediction Markets' ? t[11] : categories[rank % categories.length]
    };
  }

  const rows = Array.from({ length: 100 }, (_, i) => genRow(i + 1));

  const tbody = document.querySelector('#cryptoTable tbody');
  const categoryTabs = document.querySelectorAll('#categoryTabs .tab');
  const networkTabs = document.querySelectorAll('#networkTabs .tab');
  const pageBtns = document.querySelectorAll('.page-btn');
  const controlPanels = document.getElementById('controlPanels');
  const columnsPanel = document.getElementById('columnsPanel');
  const filtersPanel = document.getElementById('filtersPanel');

  let selectedCategory = 'Top';
  let selectedNetwork = 'All Networks';
  let selectedPage = 1;
  let minCap = 0;
  let minVol = 0;

  const fmtUSD = (v, d=2) => '$' + v.toLocaleString(undefined, { minimumFractionDigits: d, maximumFractionDigits: d });
  const fmtPct = (v) => `${v > 0 ? '+' : ''}${v.toFixed(2)}%`;
  const fmtCompact = (v) => {
    if (v >= 1e12) return `$${(v/1e12).toFixed(2)}T`;
    if (v >= 1e9) return `$${(v/1e9).toFixed(2)}B`;
    if (v >= 1e6) return `$${(v/1e6).toFixed(2)}M`;
    return fmtUSD(v, 0);
  };

  function sparklineSVG(seed, positive) {
    const points = Array.from({length: 16}, (_, i) => {
      const val = 14 + Math.sin((i + seed) * 0.65) * 7 + (positive ? i*0.2 : -i*0.12);
      return [i * 7.5 + 2, 30 - val];
    });
    const d = points.map((p, i) => `${i ? 'L':'M'}${p[0]},${p[1]}`).join(' ');
    const color = positive ? '#16c784' : '#ea3943';
    return `<svg class="spark" viewBox="0 0 120 32" aria-hidden="true"><path d="${d}" stroke="${color}" stroke-width="2" fill="none"/></svg>`;
  }

  function render() {
    let filtered = rows.filter(r => (selectedCategory === 'Top' ? true : r.category === selectedCategory));
    if (selectedNetwork !== 'All Networks') filtered = filtered.filter(r => r.network === selectedNetwork || (selectedNetwork === 'More' && !['BSC','Solana','Base','Ethereum'].includes(r.network)));
    filtered = filtered.filter(r => r.marketCap >= minCap && r.volume >= minVol);

    const pageOffset = (selectedPage - 1) * 100;
    const paged = filtered.map((r, i) => ({ ...r, rank: pageOffset + i + 1 }));

    tbody.innerHTML = paged.map((r, idx) => `
      <tr>
        <td class="rank">${r.rank}</td>
        <td class="name-cell"><strong>${r.name}</strong><span class="symbol">${r.symbol}</span></td>
        <td class="num">${r.price >= 1 ? fmtUSD(r.price, 2) : fmtUSD(r.price, 6)}</td>
        <td class="num col-h1 ${r.h1 >= 0 ? 'up' : 'down'}">${fmtPct(r.h1)}</td>
        <td class="num col-h24 ${r.h24 >= 0 ? 'up' : 'down'}">${fmtPct(r.h24)}</td>
        <td class="num col-d7 ${r.d7 >= 0 ? 'up' : 'down'}">${fmtPct(r.d7)}</td>
        <td class="num">${fmtCompact(r.marketCap)}</td>
