  const rows = Array.from({ length: 100 }, (_, i) => genRow(i + 1));

  const tbody = document.querySelector('#cryptoTable tbody');
  const categoryTabs = document.querySelectorAll('#categoryTabs .tab');
  const networkTabs = document.querySelectorAll('#networkTabs .tab');
  const pageBtns = document.querySelectorAll('.page-btn');
  const controlPanels = document.getElementById('controlPanels');
  const columnsPanel = document.getElementById('columnsPanel');
  const filtersPanel = document.getElementById('filtersPanel');

  let selectedCategory = 'Top';
  let selectedNetwork = 'All Networks';
  let selectedPage = 1;
  let minCap = 0;
  let minVol = 0;

  const fmtUSD = (v, d=2) => '$' + v.toLocaleString(undefined, { minimumFractionDigits: d, maximumFractionDigits: d });
  const fmtPct = (v) => `${v > 0 ? '+' : ''}${v.toFixed(2)}%`;
  const fmtCompact = (v) => {
    if (v >= 1e12) return `$${(v/1e12).toFixed(2)}T`;
    if (v >= 1e9) return `$${(v/1e9).toFixed(2)}B`;
    if (v >= 1e6) return `$${(v/1e6).toFixed(2)}M`;
    return fmtUSD(v, 0);
  };

  function sparklineSVG(seed, positive) {
    const points = Array.from({length: 16}, (_, i) => {
      const val = 14 + Math.sin((i + seed) * 0.65) * 7 + (positive ? i*0.2 : -i*0.12);
      return [i * 7.5 + 2, 30 - val];
    });
    const d = points.map((p, i) => `${i ? 'L':'M'}${p[0]},${p[1]}`).join(' ');
    const color = positive ? '#16c784' : '#ea3943';
    return `<svg class="spark" viewBox="0 0 120 32" aria-hidden="true"><path d="${d}" stroke="${color}" stroke-width="2" fill="none"/></svg>`;
  }

  function render() {
    let filtered = rows.filter(r => (selectedCategory === 'Top' ? true : r.category === selectedCategory));
    if (selectedNetwork !== 'All Networks') filtered = filtered.filter(r => r.network === selectedNetwork || (selectedNetwork === 'More' && !['BSC','Solana','Base','Ethereum'].includes(r.network)));
    filtered = filtered.filter(r => r.marketCap >= minCap && r.volume >= minVol);

    const pageOffset = (selectedPage - 1) * 100;
    const paged = filtered.map((r, i) => ({ ...r, rank: pageOffset + i + 1 }));

    tbody.innerHTML = paged.map((r, idx) => `
      <tr>
        <td class="rank">${r.rank}</td>
        <td class="name-cell"><strong>${r.name}</strong><span class="symbol">${r.symbol}</span></td>
        <td class="num">${r.price >= 1 ? fmtUSD(r.price, 2) : fmtUSD(r.price, 6)}</td>
        <td class="num col-h1 ${r.h1 >= 0 ? 'up' : 'down'}">${fmtPct(r.h1)}</td>
        <td class="num col-h24 ${r.h24 >= 0 ? 'up' : 'down'}">${fmtPct(r.h24)}</td>
        <td class="num col-d7 ${r.d7 >= 0 ? 'up' : 'down'}">${fmtPct(r.d7)}</td>
        <td class="num">${fmtCompact(r.marketCap)}</td>
        <td class="num col-volume">${fmtCompact(r.volume)}</td>
        <td class="num col-supply">${Math.round(r.supply).toLocaleString()} ${r.symbol}</td>
        <td class="num col-spark">${sparklineSVG(idx + selectedPage, r.d7 >= 0)}</td>
      </tr>
    `).join('');
  }

  categoryTabs.forEach(tab => tab.addEventListener('click', () => {
    categoryTabs.forEach(t => t.classList.remove('active'));
    tab.classList.add('active');
    selectedCategory = tab.dataset.category;
    render();
  }));

  networkTabs.forEach(tab => tab.addEventListener('click', () => {
    networkTabs.forEach(t => t.classList.remove('active'));
    tab.classList.add('active');
    selectedNetwork = tab.dataset.network;
    render();
  }));

  pageBtns.forEach(btn => btn.addEventListener('click', () => {
    pageBtns.forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    selectedPage = Number(btn.dataset.page);
    render();
  }));

  document.getElementById('columnsBtn').addEventListener('click', () => {
    controlPanels.classList.add('show');
    columnsPanel.style.display = columnsPanel.style.display === 'none' ? 'flex' : 'none';
  });

  document.getElementById('filtersBtn').addEventListener('click', () => {
    controlPanels.classList.add('show');
    filtersPanel.style.display = filtersPanel.style.display === 'none' ? 'flex' : 'none';
  });

  document.querySelectorAll('#columnsPanel input[type="checkbox"]').forEach(cb => {
    cb.addEventListener('change', () => {
      document.querySelectorAll(`.col-${cb.dataset.col}`).forEach(el => {
        el.style.display = cb.checked ? '' : 'none';
      });
    });
  });

  document.getElementById('applyFilters').addEventListener('click', () => {
    minCap = Number(document.getElementById('minCap').value || 0);
    minVol = Number(document.getElementById('minVol').value || 0);
    render();
  });

  document.getElementById('clearFilters').addEventListener('click', () => {
    document.getElementById('minCap').value = '';
    document.getElementById('minVol').value = '';
    minCap = 0; minVol = 0;
    render();
  });

  const extra = document.getElementById('summaryExtra');
  const readMoreBtn = document.getElementById('readMoreBtn');
  readMoreBtn.addEventListener('click', () => {
    extra.classList.toggle('show');
    readMoreBtn.textContent = extra.classList.contains('show') ? 'Read Less' : 'Read More';
  });

  const slides = document.querySelectorAll('.promo-slide');
  let slide = 0;
  function showSlide(i) {
    slides.forEach(s => s.classList.remove('active'));
    slides[i].classList.add('active');
  }
  document.querySelector('.promo-btn.prev').addEventListener('click', () => {
    slide = (slide - 1 + slides.length) % slides.length;
    showSlide(slide);
  });
  document.querySelector('.promo-btn.next').addEventListener('click', () => {
    slide = (slide + 1) % slides.length;
    showSlide(slide);
  });
  setInterval(() => {
    slide = (slide + 1) % slides.length;
    showSlide(slide);
  }, 5000);

  render();
})();
</script>
</body>
</html>
